# clip "label" <<'EOF' ... EOF  — copies stdin to the clipboard and shows a char count.
clip() {
  local label="$1" text n
  text=$(cat)
  n=${#text}
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$text" | pbcopy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$text" | xclip -selection clipboard
  else warn "no clipboard tool; the text is printed below instead"; printf '\n%s\n\n' "$text"; fi
  printf '  %s✓ copied to clipboard:%s %s %s(%s chars)%s\n' "$GREEN" "$RESET" "$label" "$DIM" "$n" "$RESET"
}

# done_mark KEY — remember a stage was completed so a re-run can skip it.
done_mark() { write_env "$1" "done" >/dev/null; }
is_done()   { [[ "$(_existing "$1" || true)" == "done" ]]; }
# skip KEY — announce a stage is being skipped and keep the counter honest.
skip() { _STAGE_INDEX=$((_STAGE_INDEX + 1)); note "stage $_STAGE_INDEX already done, skipping"; }

